function resetScene(){scene.background.set('#0a1420');scene.fog.color.set('#111d2a');moon.intensity=.6;frontDoor.rotation.y=0;carDoor.rotation.y=0;world.exitOpen=false;world.threat=0;world.shadowOnCamera=false;world.forecast=false;anomalyCheck=0;phonePulse=0;ambienceTimer=0;stalker.position.set(-10,-.17,20);stalker.visible=false;history.length=0;forecastAt=null;for(const a of actors){scene.remove(a.mesh);}actors.length=0;activeActor=null;worldKey='';for(const p of shelfPieces)p.o.position.copy(p.position);for(const p of labelPieces)p.o.rotation.y=p.rotation;}
