function sendAway(){if(!activeActor)return;activeActor.leaving=true;activeActor.ready=false;activeActor.path=[[-5.15,1.7],[5.5,1.7],[5.5,5.2],[5.5,8],[10,20]];activeActor.index=0;activeActor=null;}
function updateActors(dt,time){for(let i=actors.length-1;i>=0;i--){const a=actors[i];if(a.ready){a.deposit=Math.max(0,(a.deposit||0)-dt);a.mesh.userData.arms?.forEach(arm=>arm.rotation.x=-a.deposit);continue;}const target=a.path[a.index];if(!target){if(a.leaving){scene.remove(a.mesh);actors.splice(i,1);}else{a.ready=true;a.deposit=.8;a.mesh.rotation.y=0;counterGoods.forEach((o,i)=>o.visible=!state.scanned.includes(i));toast('KUNDE LEGT DIE WAREN AUF DIE ABLAGE');}continue;}const dx=target[0]-a.mesh.position.x,dz=target[1]-a.mesh.position.z,d=Math.hypot(dx,dz);const nearPlayer=started&&Math.hypot(a.mesh.position.x-camera.position.x,a.mesh.position.z-camera.position.z)<.6;if(nearPlayer&&d>.3){a.wait+=dt;if(a.wait>5){say(a.profile.name,'Darf ich kurz vorbei?',2500);a.wait=0;}continue;}a.mesh.rotation.y=Math.atan2(dx,dz);const speed=a.leaving?1.6:1.3;a.mesh.position.x+=dx/Math.max(d,.001)*Math.min(d,dt*speed);a.mesh.position.z+=dz/Math.max(d,.001)*Math.min(d,dt*speed);a.mesh.position.y=a.mesh.position.z>6.5?-.16:0;a.mesh.userData.legs.forEach((leg,j)=>leg.rotation.x=Math.sin(time*.007+j*Math.PI)*.34);if(d<.1)a.index++;}}
