function sync(){state=campaign.s;const key=state.night+':'+state.stage;if(key!==worldKey){worldKey=key;phaseStart=state.nightTime;world.exitOpen=false;if(campaign.job==='customer')spawnCustomer();if(campaign.job==='power'){torchOn=true;updateTorch();rumble();say('DU','Nicht jetzt. Erst Kühlung, dann Kasse, dann Licht.');}if(campaign.job==='visitor'){knock();say(campaign.visitor().name,'Hallo? Ich brauche Hilfe.',5000);}if(campaign.job==='camera'){forecastAt=null;}save();}
 counterGoods.forEach((o,i)=>o.visible=!!activeActor?.ready&&!state.scanned.includes(i));const power=campaign.job!=='power';lights.forEach(({l,base})=>l.intensity=power?base:0);fluoroMaterials.forEach(m=>m.emissiveIntensity=power?1.4:0);ambient.intensity=power?.7:.15;stockBox.visible=campaign.job==='stock'&&!state.carry;trashGroup.visible=campaign.job==='trash'&&!state.trashPicked;heldGroup.visible=state.carry==='box';heldTrash.visible=state.carry==='trash';torchGroup.visible=torchOn&&!state.carry;for(let i=0;i<stockProducts.length;i++)stockProducts[i].visible=i<state.stock*3;
 const isVisitor=campaign.job==='visitor',v=campaign.visitor();humanVisitor.visible=isVisitor&&v.human;visitor.visible=isVisitor&&!v.human;reflection.visible=isVisitor&&v.human;visitor.position.set(5.5,-.16,8.2);reflection.position.x=humanVisitor.position.x;const carPos=state.night===1?[-16,10]:state.night===2?[-7,16]:[0,10];car.position.set(carPos[0],0,carPos[1]);carDoor.rotation.y=state.night>=2&&state.stage>=5?-.8:0;carLamp.position.set(car.position.x+2,1,car.position.z);carLamp.intensity=state.night>=2?5:0;
 $('power').textContent=power?'● NETZ ONLINE':'⚡ STROMAUSFALL';$('power').style.color=power?'#a0c9b5':'#f17b77';$('held').textContent=state.carry==='box'?'CHIPSKARTON':state.carry==='trash'?'MÜLLSACK':'HÄNDE FREI';$('chapter').textContent=campaign.job==='customer'?(campaign.profile().id==='taxi'?'Der Stammkunde.':'Gesichter im Regen.'):TITLES[state.stage];$('progress').textContent=`${String(state.stage).padStart(2,'0')} / 10`;$('hint').textContent=HINTS[state.stage]();$('tasklist').innerHTML=[['Kunden bedienen',state.customers+'/2',state.customers===2],['Regale & Müll',state.stock+'/3',state.stock===3&&state.trashDone],['Lieferung & Zapfsäule','',state.delivery&&state.pumpSteps===3],['Strom & Kameras','',state.stage>7],['Besucher & Übergabe','',state.stage>8]].map(([label,count,done],i)=>`<div class="task ${done?'done':'active'}"><span class="check">${done?'✓':''}</span><span>${label} ${count}</span></div>`).join('');$('nightlabel').textContent='NACHT '+state.night+' / 3';$('fearbar').style.width=state.fear+'%';$('fearlabel').textContent=state.fear>60?'NICHT UMDREHEN':state.fear>30?'ANGESPANNT':'RUHIG';save();}
