function checkout(){if(campaign.job!=='customer'||!activeActor?.ready){toast('DER KUNDE IST NOCH AUF DEM WEG');return;}const p=campaign.profile();openModal(modalHeader('NACHT '+state.night+' / NACHTKASSE',p.name)+`<p>${esc(p.intro)}</p><div class="checkout-board"><div class="basket" id="basket">${p.items.map(([n,price],i)=>`<button class="product ${state.scanned.includes(i)?'scanned':''}" data-product="${i}" ${state.scanned.includes(i)?'disabled':''} aria-label="${n} über Scanner ziehen"><span class="packet packet-${i}">${n.split(' · ')[0]}</span><b>${n}</b><small>${euros(price)}</small></button>`).join('')}</div><div id="scanZone" class="scan-zone"><div class="scan-line"></div><span>ARTIKEL HIERHER ZIEHEN</span><small>Oder Artikel antippen / mit Enter scannen</small></div></div><div class="cash-summary"><span>${state.scanned.length}/3 Artikel</span><b>${euros(campaign.total())}</b></div>${state.scanned.length===3?`<div class="payment"><p>Der Kunde legt <b>${euros(p.paid)}</b> auf die Ablage.</p>${!state.cashTaken?'<button id="takeCash" class="primary">BARGELD ANNEHMEN</button>':`<div class="cash-summary"><span>Wechselgeld bereitgelegt</span><b>${euros(state.change)}</b></div><div class="coins">${[1,2,5,10,20,50,100,200,500].map(c=>`<button data-coin="${c}">${c>=100?euros(c):c+' ct'}</button>`).join('')}</div><button id="clearChange" class="textbtn">WECHSELGELD ZURÜCKLEGEN</button><button id="receipt" class="primary full">${state.change===p.paid-campaign.total()?'✓ ':''}WECHSELGELD GEBEN & BON DRUCKEN ↗</button>`}</div>`:'<p class="quiet">Jeden Artikel einzeln über die rote Linie ziehen. Bereits erfasste Waren werden gesperrt.</p>'}<div id="cashError" role="status"></div>`,true);
 const doScan=i=>{if(!campaign.scan(i))return;if(counterGoods[i])counterGoods[i].visible=false;beep(1400,.09);if(state.scanned.length===2&&state.night>1){world.shadowOnCamera=true;setPhone('Zähl dein Wechselgeld. Nicht die Menschen hinter dir.','UNBEKANNTE NUMMER');}save();checkout();};
 document.querySelectorAll('[data-product]').forEach(b=>{let dragged=false,startX=0,startY=0,ghost=null;const i=+b.dataset.product;b.onclick=()=>{if(!dragged)doScan(i);};b.onpointerdown=e=>{if(state.scanned.includes(i))return;startX=e.clientX;startY=e.clientY;dragged=false;b.setPointerCapture(e.pointerId);};b.onpointermove=e=>{if(!b.hasPointerCapture?.(e.pointerId))return;if(Math.hypot(e.clientX-startX,e.clientY-startY)>8){dragged=true;if(!ghost){ghost=b.cloneNode(true);ghost.className='product drag-ghost';document.body.appendChild(ghost);}ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';$('scanZone').classList.add('dragover');}};b.onpointerup=e=>{ghost?.remove();ghost=null;$('scanZone')?.classList.remove('dragover');if(dragged){const r=$('scanZone').getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)doScan(i);setTimeout(()=>dragged=false,100);}};b.onpointercancel=()=>{ghost?.remove();ghost=null;dragged=false;$('scanZone')?.classList.remove('dragover');};});
 if($('takeCash'))$('takeCash').onclick=()=>{campaign.takeCash();save();checkout();};document.querySelectorAll('[data-coin]').forEach(b=>b.onclick=()=>{campaign.change(+b.dataset.coin);beep(1100,.025,'triangle',.02);save();checkout();});if($('clearChange'))$('clearChange').onclick=()=>{state.change=0;save();checkout();};if($('receipt'))$('receipt').onclick=()=>{const result=campaign.settle();if(!result.ok){$('cashError').textContent=result.reason;beep(170,.12);return;}beep(650,.25,'triangle');sendAway();closeModal();phaseChanged();};}
function pickup(){if(campaign.pickup('box')){sync();toast('CHIPSKARTON AUFGENOMMEN');}}
function refill(i){if(campaign.stock(i)){beep(380,.08);phaseChanged();}}
function pickupTrash(){if(campaign.pickup('trash')){sync();toast('MÜLLSACK AUFGENOMMEN · CONTAINER DRAUSSEN');}}
function disposeTrash(){if(campaign.dispose()){beep(95,.2,'triangle');phaseChanged();setPhone(state.night===1?'Hast du den Wagen gesehen? Der steht seit Stunden da. Kein Kennzeichen.':'Der Wagen stand eben noch woanders. Bleib nicht zu lange draußen.','RENE / ANRUF');}else say('DU','Erst den Müllsack im Lager holen.');}
function delivery(){const m=state.manifest;openModal(modalHeader('ANLIEFERUNG / NACHT '+state.night,'Erst prüfen. Dann entscheiden.')+`<p>Der Lieferschein wurde unter der Hintertür durchgeschoben. Vom Fahrer siehst du nichts.</p><div class="receipt"><h3>NORD LOGISTIK</h3><div><span>Filiale</span><b>${m.branch}</b></div><div><span>Kartons</span><b>${m.boxes}</b></div><div><span>Zeit</span><b>${m.time}</b></div><div><span>Fahrer</span><b>${m.driver}</b></div></div><div class="note">Bestellung im Lager: NORD 17 · 12 Kartons · Fahrer H. Berger. Auch korrekte Lieferungen sind möglich.</div><button id="deliveryNo" class="choice"><b>Lieferung ablehnen</b><small>Angaben passen nicht zur Bestellung.</small></button><button id="deliveryYes" class="choice"><b>Lieferung annehmen</b><small>Filiale, Anzahl und Fahrer stimmen.</small></button>`);for(const [id,accept]of [['deliveryNo',false],['deliveryYes',true]])$(id).onclick=()=>{const correct=campaign.delivery(accept);closeModal();if(!correct)rumble();phaseChanged();};}
function pumpUI(){const steps=['Zapfpistole sicher einhängen','Störmeldung quittieren','Leitung testen und Säule freigeben'];openModal(modalHeader('VORPLATZ / ZAPFSÄULE 2','Keine Hektik im Regen.')+`<p>Die Säule meldet einen Kontaktfehler. Prüfe die Schritte der Reihe nach.</p>${steps.map((s,i)=>`<button class="choice" data-pump="${i}" ${i!==state.pumpSteps?'disabled':''}><b>${i<state.pumpSteps?'✓ ':''}${i+1}. ${s}</b></button>`).join('')}<div class="note">Wenn du Schritte hinter dir hörst, bleib kurz stehen. Dauerlicht kann Aufmerksamkeit anziehen.</div>`);document.querySelectorAll('[data-pump]').forEach(b=>b.onclick=()=>{if(!campaign.pump(+b.dataset.pump))return;beep(230,.1);if(campaign.job!=='pump'){closeModal();phaseChanged();}else{save();pumpUI();}});}
function fuseUI(){openModal(modalHeader('HAUPTVERTEILUNG','Erst Kühlung. Dann Kasse. Dann Licht.')+`<div class="note">Schichtnotiz: F2 → F1 → F3. Eine falsche Reihenfolge wirft die Sicherung erneut.</div><div class="fuses">${['F1 · KASSE','F2 · KÜHLUNG','F3 · LICHT'].map((s,i)=>`<button class="fuse ${state.fuses[i]?'on':''}" data-fuse="${i}">${s}<br>${state.fuses[i]?'EIN':'AUS'}</button>`).join('')}</div>`);document.querySelectorAll('[data-fuse]').forEach(b=>b.onclick=()=>{const result=campaign.fuse(+b.dataset.fuse);if(result==='complete'){closeModal();phaseChanged();}else{if(result==='wrong'){beep(65,.4,'sawtooth',.1);toast('FALSCHE REIHENFOLGE');}else beep(180,.08);save();fuseUI();}});}
function phoneUI(){const call=campaign.answerCall();if(!call){say('DU','Nur Rauschen.');return;}beep(300,.08);say(call.who,call.text,9000);openModal(modalHeader(call.who,'Die Leitung knistert.')+`<div class="call-wave">▂ ▄ ▆ ▃ ▇ ▅ ▂ ▄ ▆ ▂ ▃ ▅ ▇</div><p class="phone-text">„${esc(call.text)}“</p><p>Der Anruf wurde im Schichtprotokoll gespeichert. Nicht jeder Anrufer ist Mara.</p>`);save();}
function notes(){state.readNote=true;save();openModal(modalHeader('NACHT '+state.night+' / PROTOKOLL','Was du wissen solltest.')+`<div class="note">• Bestellung: <b>NORD 17 · 12 Kartons · H. Berger.</b><br>• Sicherungen: <b>F2 → F1 → F3.</b><br>• Kamera 1 zeigt den Vorplatz live, Kamera 2 den Gang verzögert.<br>• Kamera 3 sollte ausgeschaltet sein. Ihre Uhr geht vor.<br>• Menschen haben eine Spiegelung auf dem nassen Boden. Prüfe auch den Ausweis.<br>• Verweigere Hilfe nicht allein wegen eines blutigen Ärmels.<br>• Licht hält manche Schatten kurz auf. Ein langer Lichtkegel zieht sie an.<br>• Achte auf verschobene Regale, falsche Packungen, offene Türen und veränderte Fotos.</div><p><b>Aktuell:</b> ${HINTS[state.stage]()}</p><h3>Beobachtungen</h3>${state.reported.length?state.reported.map(id=>`<p>✓ ${ANOMALIES[id]}</p>`).join(''):'<p>Noch keine Veränderung gemeldet.</p>'}<h3>Telefonprotokoll</h3>${state.phoneHistory.slice(-5).map(p=>`<div class="note"><small>Nacht ${p.night} · ${esc(p.who)}</small><br>${esc(p.text)}</div>`).join('')||'<p>Noch keine Anrufe beantwortet.</p>'}`);}
function cctv(channel=selectedCamera){cctvOpened=performance.now();selectedCamera=channel;campaign.inspectCamera(channel);if(channel===2&&forecastAt===null){forecastAt=state.nightTime+12;world.forecast=true;setPhone('Du hast die falsche Kamera eingeschaltet. Die Tür wird gleich klopfen.','DEINE STIMME');}const labels=['CAM 01 / VORPLATZ · LIVE','CAM 02 / GANG · −8 SEKUNDEN','CAM 03 / KASSE · +12 SEKUNDEN'];openModal(modalHeader('ÜBERWACHUNG / NACHT '+state.night,'Drei Bilder. Eine Wirklichkeit?')+`<div class="camera-tabs">${labels.map((s,i)=>`<button data-camera="${i}" class="${i===channel?'selected':''}">${s.split(' / ')[0]}</button>`).join('')}</div><div class="cctv-frame"><span class="cctv-label">${labels[channel]}<br><span id="camtime">${clockText()}</span></span><span class="cctv-rec">● REC</span><canvas id="cctvcanvas" width="640" height="400"></canvas></div><p>${channel===0?'Prüfe den nassen Boden, die Person und den Wagen.':channel===1?'Vergleiche den Gang mit deiner direkten Sicht. Normale Bewegungen können acht Sekunden zurückliegen.':'Der Zeitstempel liegt zwölf Sekunden voraus. Die Person auf diesem Bild sollte eigentlich du sein.'}</p><p>Aufnahmen angesehen: ${state.checkedCameras.length}/3 · Meldungen am Funkgerät an der Kasse.</p>`,true);cctvCanvas=$('cctvcanvas');document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>cctv(+b.dataset.camera));save();}
function radio(){if(campaign.job==='report'){const result=campaign.completeNight();save();if(result==='next'){nightSummary();}else finish(result);return;}const ids=Object.keys(ANOMALIES);openModal(modalHeader('FUNK / KANAL 17','Beschreibe deine Beobachtung.')+`<p>Unbegründete Meldungen zählen nicht. Jede echte Veränderung kann nur einmal gemeldet werden.</p>${campaign.job==='camera'?'<button class="choice" id="reportCamera"><b>Die Gestalt ist nur auf Kamera 2 sichtbar.</b><small>Alle drei Kameras ansehen und mit dem Gang vergleichen.</small></button>':''}${ids.map(id=>`<button class="choice" data-report="${id}" ${state.reported.includes(id)?'disabled':''}><b>${state.reported.includes(id)?'✓ ':''}${ANOMALIES[id]}</b></button>`).join('')}<button class="choice" id="reportNone"><b>Keine neue Beobachtung melden.</b></button>`);$('reportNone').onclick=closeModal;if($('reportCamera'))$('reportCamera').onclick=()=>{if(state.checkedCameras.length<3){toast('ERST ALLE DREI KAMERAS PRÜFEN');return;}if(campaign.report('camera')){closeModal();phaseChanged();setPhone('Da steht wirklich jemand. Halte die Tür geschlossen, bis du den Besucher geprüft hast.','MARA / ANRUF');}};document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{if(campaign.report(b.dataset.report)){beep(650,.12);toast('BEOBACHTUNG BESTÄTIGT');}else{state.mistakes++;say('FUNK / MARA','Diese Abweichung kann ich nicht bestätigen. Schau noch einmal genau hin.');}save();closeModal();});}
function visitorUI(){const v=campaign.visitor();openModal(modalHeader('EINGANG / VERRIEGELT',v.name)+`<p>Die Person wartet im Regen. Ein blutiger Verband ist allein kein Zeichen für Gefahr.</p><div class="visitor-evidence"><button class="choice" id="askBadge"><b>Ausweis durch die Scheibe prüfen</b>${state.visitorQuestions.includes('badge')?'<small>'+v.badge+'</small>':''}</button><button class="choice" id="askStory"><b>Fragen, was passiert ist</b>${state.visitorQuestions.includes('story')?'<small>'+esc(v.answer)+'<br>'+v.voice+'</small>':''}</button><button class="choice" id="doorCamera"><b>Kamera 1 ansehen</b><small>Auf Spiegelung und Haltung achten.</small></button></div><div class="note">Spiegelung, gültiger Ausweis und eine nachvollziehbare Geschichte sind Hinweise. Eine ungewöhnliche Stimme oder unpassendes Wissen widersprechen ihnen.</div><button id="doorReject" class="choice"><b>Zutritt verweigern</b><small>Die Tür bleibt verriegelt. Auch diese Entscheidung hat Folgen.</small></button><button id="doorAccept" class="choice"><b>Person hereinlassen und Hilfe anbieten</b><small>Nur öffnen, wenn die Hinweise zusammenpassen.</small></button>`);$('askBadge').onclick=()=>{campaign.question('badge');save();visitorUI();};$('askStory').onclick=()=>{campaign.question('story');say(v.name,v.answer,8000);save();visitorUI();};$('doorCamera').onclick=()=>cctv(0);for(const [id,accept]of [['doorReject',false],['doorAccept',true]])$(id).onclick=()=>{const verdict=campaign.decideVisitor(accept);closeModal();if(verdict==='bad'){frontDoor.rotation.y=-1.1;finish('bad');return;}if(accept&&v.human){humanVisitor.visible=false;say('JOHANN','Danke. Den Verband vergesse ich dir nicht.');}else if(!accept&&v.human)say('JOHANN','Ich brauche wirklich Hilfe. Dann versuche ich es an der Straße.');else say('FUNK / MARA','Richtig entschieden. Das war kein Mitarbeiter von uns.');phaseChanged();};}
function nightSummary(){unlock();openModal(`<div class="eyebrow yellow">NACHT ${state.night} ÜBERSTANDEN</div><h2>${state.night===1?'Die Frühschicht übernimmt.':'Der Wagen ist noch da.'}</h2><p>${state.night===1?'Mara kommt kurz vor sechs. Lena hat noch einmal nach Tobias gefragt. Sein Name taucht am nächsten Abend wieder auf.':'Die Aufnahmen von 03:17 fehlen. Im Spind liegt eine Packung, die du gestern verkauft hast. Johann erinnert sich an deine Entscheidung.'}</p><div class="night-stats"><span>${state.reports} Meldungen</span><span>${state.mistakes} Fehler insgesamt</span><span>${state.phoneHistory.length} Anrufe</span></div><button id="nextNight" class="primary full">NACHT ${state.night+1} BEGINNEN ↗</button>`);$('nextNight').onclick=()=>{campaign.nextNight();state=campaign.s;resetScene();camera.position.set(-5.3,1.68,4.8);yaw=0;pitch=0;torchOn=false;updateTorch();closeModal();sync();say('DU','Gleicher Laden. Andere Nacht.',5000);};}
function finish(ending,cause='door'){if(!ending)return;ended=true;state.ending=ending;unlock();$('touch').classList.add('hidden');$('hud').classList.add('hidden');$('ending').classList.remove('hidden');localStorage.removeItem('n17-campaign');localStorage.removeItem('n17-save');if(ending==='bad'){visitor.visible=true;visitor.position.copy(camera.position).add(new T.Vector3(-Math.sin(yaw)*1.7,-1.68,-Math.cos(yaw)*1.7));rumble();lights.forEach(({l})=>l.intensity=0);ambient.intensity=.1;$('endtag').textContent='ENDE 03 / DIE OFFENE TÜR';$('endtitle').textContent='Du hast es hereingelassen.';$('endtext').textContent='Auf dem Monitor stehst du hinter der Kasse. Dein zweites Ich dreht sich um. Es nimmt das Telefon ab, bevor es klingelt. „Die Nachtschicht ist jetzt meine.“ Die Uhr bleibt auf 03:17.';if(cause==='caught'){$('endtag').textContent='ENDE 03 / DIE LETZTEN SCHRITTE';$('endtitle').textContent='Du hast zu spät hingesehen.';$('endtext').textContent='Du erreichst den Eingang nicht mehr. Hinter dir verstummen die Schritte. Auf Kamera 1 steht nur ein Schatten im Regen. Als du dich umdrehst, blickt er bereits durch deine Augen.';}beep(48,3,'sawtooth',.2);}else{scene.background.set('#536778');scene.fog.color.set('#536778');moon.intensity=1.5;ambient.intensity=.9;stalker.visible=false;visitor.visible=false;humanVisitor.visible=false;reflection.visible=false;$('endtag').textContent=ending==='good'?'ENDE 01 / FRÜHSCHICHT':'ENDE 02 / ETWAS BLEIBT';$('endtitle').textContent=ending==='good'?'Der Morgen kommt.':'Etwas ist mitgekommen.';const helped=state.decisions.some(d=>d.type==='visitor'&&d.human&&d.accept);$('endtext').textContent=ending==='good'?`Mara holt dich nach der dritten Nacht ab. ${helped?'Johann wartet am Wagen und bedankt sich für deine Hilfe.':'Der Platz vor der Tür ist leer.'} Lena findet auf dem letzten Bon eine Nachricht von Tobias: „Geh nicht wieder hin.“ Zum ersten Mal geht die Uhr weiter.`:'Du hast die Nächte überstanden, aber zu viele Warnzeichen übersehen. Zuhause klingelt dein Telefon. Deine eigene Stimme fragt, ob du die Tür öffnen kannst. Auf dem Display steht: NORD 17.';}$('endstats').innerHTML=`<div><b>${Math.max(0,100-state.mistakes*10)}</b>AUFMERKSAMKEIT</div><div><b>${state.night}/3</b>NÄCHTE</div><div><b>${state.reports}</b>MELDUNGEN</div>`;}
// Interactions stay in the world. Door opening is required to reach exterior chores.
hit('Kasse bedienen',-5.1,1.25,3.2,2.6,1.4,1.3,checkout,'Artikel ziehen · Bargeld · Wechselgeld',()=>campaign.job==='customer'&&!!activeActor?.ready);
hit('Warenkarton aufnehmen',6.2,.65,-7,1.3,1.3,1.1,pickup,'Chips für Gang 2',()=>campaign.job==='stock'&&!state.carry);
for(let i=0;i<3;i++){const z=-3.05+i*1.5;sign(`${i+1} · NACHFÜLLEN`,3.79,1.8,z,.9,.2,{rot:Math.PI/2,bg:'#ba9c4b',color:'#222929',size:36});hit('Regalfach auffüllen',3.82,1.5,z,.5,1.5,1.15,()=>refill(i),`Fach ${i+1} von 3`,()=>campaign.job==='stock'&&state.carry==='box'&&i===state.stock);}
hit('Müllsack aufnehmen',7.5,.65,-6.8,1,1.3,1,pickupTrash,'Zum Außencontainer links vom Shop',()=>campaign.job==='trash'&&!state.carry);
hit('Müll entsorgen',-8,.9,10.7,2,1.8,1.5,disposeTrash,'Container · RESTMÜLL',()=>campaign.job==='trash');
hit('Lieferung prüfen',7.1,1.35,-8.15,1.6,2.5,.35,delivery,'NORD 17 · 12 Kartons · H. Berger',()=>campaign.job==='delivery');
hit('Zapfsäule 2 prüfen',0,1.1,14,1.5,2.2,1.3,pumpUI,'Kontaktfehler · Drei Prüfschritte',()=>campaign.job==='pump');
hit('Sicherungskasten öffnen',8.48,1.5,3.3,.6,1.5,1.2,fuseUI,'F1 Kasse · F2 Kühlung · F3 Licht',()=>campaign.job==='power');
hit('Überwachung ansehen',4.8,2.2,-5.4,2,1.6,.5,()=>cctv(),'Drei Kameras · verschiedene Zeiten');
hit('Funkgerät benutzen',-7.4,1.4,3.35,.8,.8,.6,radio,'Beobachtungen melden · Schicht beenden');
hit('Telefon abnehmen',-3.25,1.35,3.35,.8,.8,.6,phoneUI,'Unbekannter Anruf',()=>!!state.phone);
hit('Schichtnotiz lesen',-8.55,1.8,4.65,.6,1.4,1.7,notes,'Regeln · Anrufe · Beobachtungen');
hit('Vermisstenfoto ansehen',-2.5,1.9,-5.5,1.1,1.1,.5,()=>{openModal(modalHeader('AUSHANG / VERMISST',alteredPoster.visible?'Das ist dein Name.':'Tobias Keller.')+`<p>${alteredPoster.visible?'Auf dem Foto steht jetzt ALEX. Darunter: Seit heute, 03:17. Du hast dieses Blatt nicht aufgehängt.':state.night===1?'Lena sucht ihren Mann Tobias. Dunkle Haare, Arbeitsmantel. Er wollte an dieser Tankstelle nur kurz tanken.':'Der Mann im Arbeitsmantel sieht aus wie Tobias auf diesem Aushang. Auf dem Foto hat er dieselbe kleine Narbe über der linken Augenbraue.'}</p>`);},'Das Foto mit den Kunden vergleichen');
hit('Spind prüfen',5.15,1,-7.3,.9,2,.7,()=>{openModal(modalHeader('PERSÖNLICHER SPIND / ALEX','Das gehört nicht hierher.')+`<p>${stolenGoods.visible?'Eine Chipspackung liegt im Spind. Auf dem Etikett steht deine letzte Bonnummer. Du hast sie verkauft.':'Dein Namensschild und die alte Schichtnotiz. Sonst nichts.'}</p><div class="note">Mara: „Lass den Spind abgeschlossen. Auch während du draußen bist.“</div>`);},'Dein Fach · ALEX');
hit('Besucher überprüfen',5.5,1.4,6.25,2.4,2.8,.6,visitorUI,'Ausweis · Geschichte · Spiegelung',()=>campaign.job==='visitor');
hit('Eingang öffnen / schließen',5.5,1.3,6.5,2.1,2.6,.4,()=>{world.exitOpen=!world.exitOpen;beep(190,.08);toast(world.exitOpen?'EINGANG GEÖFFNET':'EINGANG GESCHLOSSEN');},'Zugang zu Müllcontainer und Zapfsäulen',()=>campaign.job!=='visitor');
hit('Kaffee trinken',-8.1,1.4,-1.6,1,1,.8,()=>{stamina=1;state.fear=Math.max(0,state.fear-8);say('DU',state.night===1?'Kalt. Natürlich.':'Rene bestellt immer Kaffee. Tobias hat seinen nie abgeholt.');sync();},'Ein kurzer Moment Ruhe.');
const raycaster=new T.Raycaster();raycaster.far=3.4;
function findTarget(){scene.updateMatrixWorld();camera.updateMatrixWorld();raycaster.setFromCamera(new T.Vector2(0,0),camera);const valid=interactives.filter(i=>i.enabled()),hits=raycaster.intersectObjects(valid.map(i=>i.mesh),false);currentTarget=hits.length?valid.find(i=>i.mesh===hits[0].object):null;if(currentTarget){$('interaction').classList.remove('hidden');$('action').textContent=currentTarget.name;$('actiondesc').textContent=currentTarget.description;$('reticle').classList.add('ready');}else{$('interaction').classList.add('hidden');$('reticle').classList.remove('ready');}}
function interact(){if(!started||paused||modalOpen||ended||interactionCooldown>0)return;if(currentTarget){interactionCooldown=.2;currentTarget.action();}else toast('NÄHER HERANGEHEN UND AUF DAS OBJEKT SCHAUEN');}
function setPause(value){if(!started||ended)return;paused=value;$('pause').classList.toggle('hidden',!value);if(value){unlock();$('touch').classList.add('hidden');$('interaction').classList.add('hidden');}else{if(touch)$('touch').classList.remove('hidden');lock();}Object.keys(keys).forEach(k=>keys[k]=false);moveX=moveY=0;}
function loadCampaign(){let saved=null;try{saved=JSON.parse(localStorage.getItem('n17-campaign'));if(!saved){saved=migrateLegacy(JSON.parse(localStorage.getItem('n17-save')));if(saved)toast('ALTER SPIELSTAND IN DIE KAMPAGNE ÜBERNOMMEN');}}catch{}return makeCampaign(Date.now(),saved);}
function startGame(resume=false){initAudio();campaign=resume?loadCampaign():makeCampaign(Date.now());state=campaign.s;started=true;paused=false;ended=false;$('menu').classList.add('hidden');$('pause').classList.add('hidden');$('ending').classList.add('hidden');$('hud').classList.remove('hidden');if(touch)$('touch').classList.remove('hidden');resetScene();camera.position.set(-5.3,1.68,4.8);yaw=0;pitch=-.02;torchOn=campaign.job==='power';updateTorch();sync();lock();if(state.interlude){nightSummary();}else if(state.ending){finish(state.ending);}else say('DU',resume?'Okay. Weiterarbeiten.':'Alex. Nachtdienst. Drei Nächte, dann habe ich frei.',6500);}
$('start').onclick=()=>startGame();$('continue').onclick=()=>startGame(true);if(localStorage.getItem('n17-campaign')||localStorage.getItem('n17-save'))$('continue').classList.remove('hidden');$('resume').onclick=()=>setPause(false);$('restart').onclick=()=>{openModal(modalHeader('NEUE KAMPAGNE','Wieder bei Nacht eins beginnen?')+'<p>Dein gespeicherter Kampagnenfortschritt wird ersetzt.</p><button id="confirmrestart" class="primary">DREI NEUE NÄCHTE STARTEN</button>');$('confirmrestart').onclick=()=>{closeModal();startGame(false);};};$('again').onclick=()=>location.reload();$('settingsBtn').onclick=settingsUI;$('pauseSettings').onclick=settingsUI;$('notesBtn').onclick=notes;$('brand').onclick=e=>{e.preventDefault();if(started)setPause(!paused);};
document.addEventListener('keydown',e=>{if(['Tab','Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat){keys[e.code]=true;return;}if(e.code==='Escape'){if(modalOpen&&!state.interlude)closeModal();else if(!modalOpen)setPause(!paused);return;}if(e.code==='Tab'&&started&&!ended&&!state.interlude){if(modalOpen)closeModal();else notes();return;}if(e.code==='KeyE'&&!modalOpen)interact();if(e.code==='KeyQ'&&modalOpen&&$('doorReject'))$('doorReject').click();if(e.code==='KeyF')toggleTorch();keys[e.code]=true;});document.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousemove',e=>{if(document.pointerLockElement!==$('game')||modalOpen||paused)return;yaw-=e.movementX*.002*settings.sensitivity;pitch=Math.max(-1.35,Math.min(1.35,pitch-e.movementY*.002*settings.sensitivity));});
$('game').addEventListener('click',()=>{if(!started||modalOpen||paused||ended)return;if(!touch&&document.pointerLockElement!==$('game'))lock();else interact();});
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&started&&!modalOpen&&!paused&&!ended&&!touch)setPause(true);});
window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);moveX=moveY=0;if(started&&!ended&&!modalOpen)setPause(true);});
$('touchE').onclick=interact;$('touchF').onclick=toggleTorch;$('touchPause').onclick=()=>setPause(true);$('touchNotes').onclick=notes;$('touchQ').onclick=()=>{if(campaign.job==='visitor'&&currentTarget?.name==='Besucher überprüfen')visitorUI();else notes();};
const look=$('lookzone');look.onpointerdown=e=>{lookPointer={id:e.pointerId,x:e.clientX,y:e.clientY};look.setPointerCapture(e.pointerId);};look.onpointermove=e=>{if(!lookPointer||lookPointer.id!==e.pointerId)return;const dx=e.clientX-lookPointer.x,dy=e.clientY-lookPointer.y;yaw-=dx*.005*settings.sensitivity;pitch=Math.max(-1.2,Math.min(1.2,pitch-dy*.005*settings.sensitivity));lookPointer.x=e.clientX;lookPointer.y=e.clientY;};look.onpointerup=look.onpointercancel=()=>lookPointer=null;
const joy=$('joystick');function updateJoystick(e){const r=joy.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,d=Math.hypot(x,y),limit=36;moveX=x/Math.max(limit,d);moveY=y/Math.max(limit,d);$('knob').style.transform=`translate(${moveX*limit}px,${moveY*limit}px)`;}joy.onpointerdown=e=>{joystickPointer=e.pointerId;joy.setPointerCapture(e.pointerId);updateJoystick(e);};joy.onpointermove=e=>{if(joystickPointer===e.pointerId)updateJoystick(e);};joy.onpointerup=joy.onpointercancel=()=>{joystickPointer=null;moveX=moveY=0;$('knob').style.transform='';};
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
function canStand(x,z){if(z<6.1){if(x< -8.55||x>8.55||z< -8.05)return false;}else if(z<6.95){if(x<4.65||x>6.45||frontDoor.rotation.y>-.65)return false;}else if(x< -18||x>18||z>24)return false;for(const c of colliders){if(x>c.x-c.w-.23&&x<c.x+c.w+.23&&z>c.z-c.d-.23&&z<c.z+c.d+.23)return false;}for(const a of actors){if(Math.hypot(x-a.mesh.position.x,z-a.mesh.position.z)<.4)return false;}return true;}
function lookingAt(position,threshold=.65){const dir=new T.Vector3();camera.getWorldDirection(dir);const to=position.clone().sub(camera.position);to.y=0;return dir.dot(to.normalize())>threshold;}
function applyAnomalies(){const active=id=>state.anomalies.some(a=>a.id===id&&a.active)&&!state.reported.includes(id);const offset=active('shelf') ? .55 : 0;for(const p of shelfPieces)p.o.position.x=p.position.x+offset;for(const c of colliders){if(c.shelfOrigin===undefined&&c.x===-.8)c.shelfOrigin=c.x;if(c.shelfOrigin!==undefined)c.x=c.shelfOrigin+offset;}for(const p of labelPieces){p.o.rotation.y=p.rotation+(active('labels')?Math.PI:0);p.o.material=active('labels')?reversePacket:p.o.userData.originalMaterial;}alteredPoster.visible=active('poster');stolenGoods.visible=active('locker');return active;}
