 if(threatActive){const distance=stalker.position.distanceTo(camera.position),watched=lookingAt(stalker.position,.75),beam=torchOn&&watched&&distance<17;state.flashExposure=Math.max(0,state.flashExposure+dt*(beam?1:-2));if(!watched||state.flashExposure>2.3){const delta=camera.position.clone().sub(stalker.position);delta.y=0;stalker.position.addScaledVector(delta.normalize(),dt*(state.flashExposure>2.3?1.2:.6));stalker.rotation.y=Math.atan2(delta.x,delta.z);}state.fear=T.MathUtils.clamp(state.fear+dt*(distance<2?12:distance<5?3.5:1),0,100);if(state.flashExposure>2.3){$('torchstatus').textContent='LICHT ZIEHT ES AN';$('torchstatus').style.color='#ef807e';}if(state.fear>=100){finish('bad','caught');return;}}else{state.flashExposure=0;if(!outside)stalker.position.set(-10,-.17,20);state.fear=Math.max(0,state.fear-dt*(outside ? .3 : 1.7));}
